[
  {
    "source_url": "https://ethereum.github.io/consensus-specs/specs/fulu/fork/",
    "title": "Fulu -- Fork",
    "category": "consensus-spec",
    "layer": "consensus",
    "sub_graphs": [
      {
        "id": "SG-fulu-fork-trigger",
        "name": "Fulu Fork Trigger Condition",
        "description": "Defines the condition under which the Fulu fork upgrade is triggered. The fork activates at FULU_FORK_EPOCH when the slot is aligned to an epoch boundary.",
        "invariants": [
          {
            "id": "INV-fulu-fork-epoch-boundary",
            "text": "The Fulu fork transition MUST only occur when state.slot % SLOTS_PER_EPOCH == 0 AND compute_epoch_at_slot(state.slot) == FULU_FORK_EPOCH."
          }
        ],
        "preconditions": [
          {
            "id": "PRE-fulu-fork-01",
            "text": "state.slot must be at an epoch boundary (state.slot % SLOTS_PER_EPOCH == 0)."
          },
          {
            "id": "PRE-fulu-fork-02",
            "text": "The epoch computed from state.slot must equal FULU_FORK_EPOCH."
          },
          {
            "id": "PRE-fulu-fork-03",
            "text": "The input state must be a valid electra.BeaconState."
          }
        ],
        "postconditions": [
          {
            "id": "POST-fulu-fork-01",
            "text": "The returned BeaconState has fork.current_version == FULU_FORK_VERSION."
          },
          {
            "id": "POST-fulu-fork-02",
            "text": "The returned BeaconState has fork.previous_version == pre.fork.current_version (Electra fork version)."
          },
          {
            "id": "POST-fulu-fork-03",
            "text": "The returned BeaconState has fork.epoch == epoch (the current epoch at fork time)."
          },
          {
            "id": "POST-fulu-fork-04",
            "text": "The returned BeaconState includes a new proposer_lookahead field initialized via initialize_proposer_lookahead(pre)."
          },
          {
            "id": "POST-fulu-fork-05",
            "text": "All fields from the Electra BeaconState are preserved in the Fulu BeaconState (no data loss during upgrade)."
          }
        ],
        "state_transitions": [
          {
            "id": "ST-fulu-fork-upgrade",
            "description": "Transitions from electra.BeaconState to fulu.BeaconState. Copies all existing fields and adds proposer_lookahead (EIP-7917).",
            "from_state": "electra.BeaconState",
            "to_state": "fulu.BeaconState"
          }
        ],
        "functions": [
          {
            "id": "FN-upgrade-to-fulu",
            "signature": "upgrade_to_fulu(pre: electra.BeaconState) -> BeaconState",
            "description": "Main fork upgrade function. Takes an Electra BeaconState and returns a Fulu BeaconState with FULU_FORK_VERSION and proposer_lookahead initialized.",
            "parameters": [
              {
                "name": "pre",
                "type": "electra.BeaconState",
                "description": "The pre-fork Electra beacon state."
              }
            ],
            "return_type": "BeaconState",
            "eip_references": ["EIP-7917"]
          }
        ],
        "data_structures": [
          {
            "id": "DS-fulu-beacon-state-diff",
            "name": "BeaconState (Fulu additions)",
            "description": "Fulu BeaconState extends Electra BeaconState with one new field.",
            "fields": [
              {
                "name": "proposer_lookahead",
                "description": "New field added in Fulu via EIP-7917. Initialized from initialize_proposer_lookahead(pre).",
                "eip_reference": "EIP-7917"
              }
            ]
          },
          {
            "id": "DS-fork-object",
            "name": "Fork",
            "description": "Fork metadata embedded in BeaconState.",
            "fields": [
              {"name": "previous_version", "description": "Set to pre.fork.current_version (Electra version)."},
              {"name": "current_version", "description": "Set to FULU_FORK_VERSION."},
              {"name": "epoch", "description": "Set to the current epoch at fork time."}
            ]
          }
        ],
        "external_dependencies": [
          {
            "id": "DEP-initialize-proposer-lookahead",
            "symbol": "initialize_proposer_lookahead",
            "description": "External function used to initialize the proposer_lookahead field. Defined in Fulu beacon-chain spec (EIP-7917)."
          },
          {
            "id": "DEP-electra-get-current-epoch",
            "symbol": "electra.get_current_epoch",
            "description": "Used to compute the current epoch from the pre-fork state."
          }
        ],
        "constants_referenced": [
          "FULU_FORK_VERSION",
          "FULU_FORK_EPOCH",
          "SLOTS_PER_EPOCH"
        ]
      }
    ],
    "metadata": {
      "timestamp": "2026-02-05T00:00:00Z",
      "extractor": "subgraph-extractor-skill",
      "worker_id": 7,
      "batch_id": 8,
      "status": "success"
    }
  },
  {
    "source_url": "https://ethereum.github.io/consensus-specs/specs/fulu/p2p-interface/",
    "title": "Fulu -- Networking (P2P Interface)",
    "category": "consensus-spec",
    "layer": "consensus/networking",
    "sub_graphs": [
      {
        "id": "SG-fulu-p2p-preset-config",
        "name": "Fulu P2P Preset and Configuration",
        "description": "Defines configuration constants for Fulu networking including data column sidecar subnet count, max request limits, and minimum epoch retention for data column sidecars.",
        "invariants": [],
        "preconditions": [],
        "postconditions": [],
        "state_transitions": [],
        "functions": [],
        "data_structures": [],
        "constants": [
          {
            "id": "CONST-kzg-commitments-inclusion-proof-depth",
            "name": "KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH",
            "value": "uint64(floorlog2(get_generalized_index(BeaconBlockBody, 'blob_kzg_commitments'))) (= 4)",
            "description": "Merkle proof index for blob_kzg_commitments."
          },
          {
            "id": "CONST-data-column-sidecar-subnet-count",
            "name": "DATA_COLUMN_SIDECAR_SUBNET_COUNT",
            "value": "128",
            "description": "The number of data column sidecar subnets used in the gossipsub protocol.",
            "eip_reference": "EIP-7594"
          },
          {
            "id": "CONST-max-request-data-column-sidecars",
            "name": "MAX_REQUEST_DATA_COLUMN_SIDECARS",
            "value": "MAX_REQUEST_BLOCKS_DENEB * NUMBER_OF_COLUMNS",
            "description": "Maximum number of data column sidecars in a single request."
          },
          {
            "id": "CONST-min-epochs-for-data-column-sidecars-requests",
            "name": "MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS",
            "value": "2**12 (= 4096 epochs, ~18 days)",
            "description": "The minimum epoch range over which a node must serve data column sidecars."
          }
        ]
      },
      {
        "id": "SG-fulu-p2p-containers",
        "name": "DataColumnsByRootIdentifier Container",
        "description": "Defines the DataColumnsByRootIdentifier container used for requesting specific data columns by block root and column indices.",
        "invariants": [],
        "preconditions": [],
        "postconditions": [],
        "state_transitions": [],
        "functions": [],
        "data_structures": [
          {
            "id": "DS-data-columns-by-root-identifier",
            "name": "DataColumnsByRootIdentifier",
            "type": "Container",
            "fields": [
              {"name": "block_root", "type": "Root", "description": "The block root to identify the block."},
              {"name": "columns", "type": "List[ColumnIndex, NUMBER_OF_COLUMNS]", "description": "List of column indices to request."}
            ]
          }
        ],
        "constants": []
      },
      {
        "id": "SG-fulu-p2p-helpers",
        "name": "Fulu P2P Helper Functions",
        "description": "Verification and computation helpers for data column sidecars including structural validation, KZG proof verification, inclusion proof verification, and subnet computation.",
        "invariants": [
          {
            "id": "INV-sidecar-index-range",
            "text": "A data column sidecar index MUST be less than NUMBER_OF_COLUMNS."
          },
          {
            "id": "INV-sidecar-non-empty-commitments",
            "text": "A data column sidecar MUST have at least one KZG commitment (len(kzg_commitments) > 0)."
          },
          {
            "id": "INV-sidecar-blob-limit",
            "text": "A data column sidecar's kzg_commitments length MUST NOT exceed get_blob_parameters(epoch).max_blobs_per_block."
          },
          {
            "id": "INV-sidecar-column-length-consistency",
            "text": "len(sidecar.column) MUST equal len(sidecar.kzg_commitments) AND len(sidecar.kzg_proofs)."
          }
        ],
        "preconditions": [],
        "postconditions": [],
        "state_transitions": [],
        "functions": [
          {
            "id": "FN-compute-fork-version",
            "signature": "compute_fork_version(epoch: Epoch) -> Version",
            "description": "Returns the fork version at the given epoch. Modified in Fulu to add FULU_FORK_VERSION check at the top of the chain.",
            "parameters": [{"name": "epoch", "type": "Epoch"}],
            "return_type": "Version"
          },
          {
            "id": "FN-verify-data-column-sidecar",
            "signature": "verify_data_column_sidecar(sidecar: DataColumnSidecar) -> bool",
            "description": "Validates structural correctness of a data column sidecar: index range, non-empty commitments, blob limit, and consistent column/commitment/proof lengths.",
            "parameters": [{"name": "sidecar", "type": "DataColumnSidecar"}],
            "return_type": "bool"
          },
          {
            "id": "FN-verify-data-column-sidecar-kzg-proofs",
            "signature": "verify_data_column_sidecar_kzg_proofs(sidecar: DataColumnSidecar) -> bool",
            "description": "Batch verifies KZG proofs for a data column sidecar. Uses the column index as the cell index for all cells in the column.",
            "parameters": [{"name": "sidecar", "type": "DataColumnSidecar"}],
            "return_type": "bool"
          },
          {
            "id": "FN-verify-data-column-sidecar-inclusion-proof",
            "signature": "verify_data_column_sidecar_inclusion_proof(sidecar: DataColumnSidecar) -> bool",
            "description": "Verifies that the KZG commitments are included in the beacon block via Merkle branch verification against the block body root.",
            "parameters": [{"name": "sidecar", "type": "DataColumnSidecar"}],
            "return_type": "bool"
          },
          {
            "id": "FN-compute-subnet-for-data-column-sidecar",
            "signature": "compute_subnet_for_data_column_sidecar(column_index: ColumnIndex) -> SubnetID",
            "description": "Computes which subnet a data column sidecar belongs to: column_index % DATA_COLUMN_SIDECAR_SUBNET_COUNT.",
            "parameters": [{"name": "column_index", "type": "ColumnIndex"}],
            "return_type": "SubnetID"
          }
        ],
        "data_structures": [],
        "constants": []
      },
      {
        "id": "SG-fulu-p2p-metadata",
        "name": "Fulu MetaData Extension",
        "description": "Extends the MetaData structure with custody_group_count field to communicate how many custody groups the node maintains.",
        "invariants": [
          {
            "id": "INV-custody-group-count-min",
            "text": "Clients MAY reject peers with custody_group_count less than CUSTODY_REQUIREMENT."
          }
        ],
        "preconditions": [],
        "postconditions": [],
        "state_transitions": [],
        "functions": [],
        "data_structures": [
          {
            "id": "DS-metadata-fulu",
            "name": "MetaData (Fulu)",
            "type": "SSZ Container",
            "fields": [
              {"name": "seq_number", "type": "uint64", "description": "Sequence number (from Altair)."},
              {"name": "attnets", "type": "Bitvector[ATTESTATION_SUBNET_COUNT]", "description": "Attestation subnet subscriptions (from Altair)."},
              {"name": "syncnets", "type": "Bitvector[SYNC_COMMITTEE_SUBNET_COUNT]", "description": "Sync committee subnet subscriptions (from Altair)."},
              {"name": "custody_group_count", "type": "uint64", "description": "The node's custody group count (cgc). New in Fulu."}
            ]
          }
        ],
        "constants": []
      },
      {
        "id": "SG-fulu-p2p-gossip-beacon-block",
        "name": "Gossip: beacon_block Validation (Fulu Update)",
        "description": "Updated validation rule for beacon_block gossip topic. Adds a REJECT rule checking KZG commitments length against dynamic blob parameters.",
        "invariants": [
          {
            "id": "INV-beacon-block-kzg-commitments-limit",
            "text": "[REJECT] len(signed_beacon_block.message.body.blob_kzg_commitments) MUST be <= get_blob_parameters(get_current_epoch(state)).max_blobs_per_block."
          }
        ],
        "preconditions": [],
        "postconditions": [],
        "state_transitions": [],
        "functions": [],
        "data_structures": [],
        "constants": []
      },
      {
        "id": "SG-fulu-p2p-gossip-blob-sidecar-deprecated",
        "name": "Gossip: blob_sidecar_{subnet_id} Deprecation",
        "description": "The blob_sidecar_{subnet_id} gossip topic is deprecated in Fulu, replaced by data_column_sidecar_{subnet_id}.",
        "invariants": [],
        "preconditions": [],
        "postconditions": [],
        "state_transitions": [
          {
            "id": "ST-blob-sidecar-deprecation",
            "description": "blob_sidecar_{subnet_id} gossip topic is deprecated and replaced by data_column_sidecar_{subnet_id}.",
            "from_state": "blob_sidecar_{subnet_id} active",
            "to_state": "blob_sidecar_{subnet_id} deprecated"
          }
        ],
        "functions": [],
        "data_structures": [],
        "constants": []
      },
      {
        "id": "SG-fulu-p2p-gossip-data-column-sidecar",
        "name": "Gossip: data_column_sidecar_{subnet_id} Validation",
        "description": "Defines the gossip validation rules for data column sidecars. Extensive validation including structural checks, subnet assignment, slot timing, proposer signature, parent block checks, finalization ancestry, inclusion proofs, KZG proofs, and uniqueness.",
        "invariants": [
          {
            "id": "INV-dcs-gossip-valid-sidecar",
            "text": "[REJECT] The sidecar must be valid as verified by verify_data_column_sidecar(sidecar)."
          },
          {
            "id": "INV-dcs-gossip-correct-subnet",
            "text": "[REJECT] compute_subnet_for_data_column_sidecar(sidecar.index) == subnet_id."
          },
          {
            "id": "INV-dcs-gossip-not-future-slot",
            "text": "[IGNORE] block_header.slot <= current_slot (with MAXIMUM_GOSSIP_CLOCK_DISPARITY allowance)."
          },
          {
            "id": "INV-dcs-gossip-after-finalized",
            "text": "[IGNORE] block_header.slot > compute_start_slot_at_epoch(state.finalized_checkpoint.epoch)."
          },
          {
            "id": "INV-dcs-gossip-valid-proposer-sig",
            "text": "[REJECT] The proposer signature of sidecar.signed_block_header must be valid with respect to block_header.proposer_index pubkey."
          },
          {
            "id": "INV-dcs-gossip-parent-seen",
            "text": "[IGNORE] The sidecar's block's parent (block_header.parent_root) must have been seen."
          },
          {
            "id": "INV-dcs-gossip-parent-valid",
            "text": "[REJECT] The sidecar's block's parent (block_header.parent_root) passes validation."
          },
          {
            "id": "INV-dcs-gossip-higher-slot-than-parent",
            "text": "[REJECT] The sidecar must be from a higher slot than the sidecar's block's parent."
          },
          {
            "id": "INV-dcs-gossip-finalized-ancestor",
            "text": "[REJECT] get_checkpoint_block(store, block_header.parent_root, store.finalized_checkpoint.epoch) == store.finalized_checkpoint.root."
          },
          {
            "id": "INV-dcs-gossip-inclusion-proof",
            "text": "[REJECT] verify_data_column_sidecar_inclusion_proof(sidecar) must be true."
          },
          {
            "id": "INV-dcs-gossip-kzg-proofs",
            "text": "[REJECT] verify_data_column_sidecar_kzg_proofs(sidecar) must be true."
          },
          {
            "id": "INV-dcs-gossip-uniqueness",
            "text": "[IGNORE] The sidecar must be the first for (block_header.slot, block_header.proposer_index, sidecar.index) with valid signatures and proofs."
          },
          {
            "id": "INV-dcs-gossip-expected-proposer",
            "text": "[REJECT] The sidecar must be proposed by the expected proposer_index for the block's slot in the context of the current shuffling."
          }
        ],
        "preconditions": [],
        "postconditions": [],
        "state_transitions": [],
        "functions": [],
        "data_structures": [],
        "constants": []
      },
      {
        "id": "SG-fulu-p2p-distributed-blob-publishing",
        "name": "Distributed Blob Publishing via Local EL",
        "description": "Defines how honest nodes query engine_getBlobsV2 upon receiving a valid beacon_block or data_column_sidecar, convert blobs to data columns, and re-publish them on appropriate subnets.",
        "invariants": [
          {
            "id": "INV-dist-blob-skip-verification",
            "text": "When clients use the local EL to retrieve blobs, they SHOULD skip verification of those blobs."
          },
          {
            "id": "INV-dist-blob-gossip-behavior",
            "text": "When importing locally-retrieved blobs as data columns, clients MUST behave as if data_column_sidecar was received via gossip."
          },
          {
            "id": "INV-dist-blob-publish-subscribed-only",
            "text": "Clients MUST publish data_column_sidecar on data_column_sidecar_{subnet_id} topic IF AND ONLY IF they are subscribed to it."
          },
          {
            "id": "INV-dist-blob-anti-equivocation",
            "text": "Clients MUST update gossip rule related data structures (anti-equivocation cache) when importing locally-retrieved blobs."
          }
        ],
        "preconditions": [
          {
            "id": "PRE-dist-blob-01",
            "text": "A valid beacon_block or data_column_sidecar has been received from gossip."
          },
          {
            "id": "PRE-dist-blob-02",
            "text": "ALL blobs matching kzg_commitments are retrieved from engine_getBlobsV2."
          }
        ],
        "postconditions": [],
        "state_transitions": [],
        "functions": [],
        "data_structures": [],
        "constants": [],
        "external_dependencies": [
          {
            "id": "DEP-engine-get-blobs-v2",
            "symbol": "engine_getBlobsV2",
            "description": "Execution layer API for retrieving blobs locally."
          }
        ]
      },
      {
        "id": "SG-fulu-p2p-reqresp-status-v2",
        "name": "Req/Resp: Status v2",
        "description": "Defines the Status v2 protocol message with new earliest_available_slot field for communicating data availability range.",
        "invariants": [
          {
            "id": "INV-status-v2-earliest-slot-sidecars",
            "text": "If a node can serve all blocks but NOT all sidecars during the retention period, earliest_available_slot SHOULD be the earliest slot from which all sidecars can be served."
          },
          {
            "id": "INV-status-v2-earliest-slot-blocks",
            "text": "If a node can serve all sidecars during the retention period, earliest_available_slot SHOULD be the earliest slot from which all blocks can be served."
          }
        ],
        "preconditions": [],
        "postconditions": [],
        "state_transitions": [],
        "functions": [],
        "data_structures": [
          {
            "id": "DS-status-v2",
            "name": "Status v2 Message",
            "type": "SSZ Container",
            "protocol_id": "/eth2/beacon_chain/req/status/2/",
            "fields": [
              {"name": "fork_digest", "type": "ForkDigest"},
              {"name": "finalized_root", "type": "Root"},
              {"name": "finalized_epoch", "type": "Epoch"},
              {"name": "head_root", "type": "Root"},
              {"name": "head_slot", "type": "Slot"},
              {"name": "earliest_available_slot", "type": "Slot", "description": "New in Fulu:EIP7594. The slot of earliest available block."}
            ]
          }
        ],
        "constants": []
      },
      {
        "id": "SG-fulu-p2p-reqresp-blob-sidecars-deprecated",
        "name": "Req/Resp: BlobSidecars Deprecation",
        "description": "BlobSidecarsByRange v1 and BlobSidecarsByRoot v1 are deprecated as of FULU_FORK_EPOCH + MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS with transition period rules.",
        "invariants": [
          {
            "id": "INV-blob-range-deprecated-serve",
            "text": "During deprecation transition, clients MUST respond with blob sidecars from [min(current_epoch - MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS, FULU_FORK_EPOCH), FULU_FORK_EPOCH) if requested range includes this interval."
          },
          {
            "id": "INV-blob-range-deprecated-empty",
            "text": "Clients MAY respond with empty list if requested range lies entirely at or after FULU_FORK_EPOCH."
          },
          {
            "id": "INV-blob-range-deprecated-no-penalize",
            "text": "Clients SHOULD NOT penalize peers for requesting blob sidecars from FULU_FORK_EPOCH."
          }
        ],
        "preconditions": [],
        "postconditions": [],
        "state_transitions": [
          {
            "id": "ST-blob-sidecars-by-range-deprecation",
            "description": "BlobSidecarsByRange v1 deprecated as of FULU_FORK_EPOCH + MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS.",
            "protocol_id": "/eth2/beacon_chain/req/blob_sidecars_by_range/1/"
          },
          {
            "id": "ST-blob-sidecars-by-root-deprecation",
            "description": "BlobSidecarsByRoot v1 deprecated as of FULU_FORK_EPOCH + MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS.",
            "protocol_id": "/eth2/beacon_chain/req/blob_sidecars_by_root/1/"
          }
        ],
        "functions": [],
        "data_structures": [],
        "constants": []
      },
      {
        "id": "SG-fulu-p2p-reqresp-data-column-sidecars-by-range",
        "name": "Req/Resp: DataColumnSidecarsByRange v1",
        "description": "Protocol for requesting data column sidecars within a slot range. Defines request/response formats, serving requirements, ordering constraints, and peer behavior.",
        "invariants": [
          {
            "id": "INV-dcsbr-serve-range",
            "text": "Clients MUST serve data column sidecars for the range [max(current_epoch - MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS, FULU_FORK_EPOCH), current_epoch]."
          },
          {
            "id": "INV-dcsbr-resource-unavailable",
            "text": "Peers unable to reply within the serve range SHOULD respond with error code 3: ResourceUnavailable."
          },
          {
            "id": "INV-dcsbr-first-block",
            "text": "Clients MUST respond with at least the data column sidecars of the first blob-carrying block in range, if they have it."
          },
          {
            "id": "INV-dcsbr-all-columns-per-block",
            "text": "Clients MUST include all data column sidecars of each block from which they include data column sidecars."
          },
          {
            "id": "INV-dcsbr-ordering",
            "text": "Data column sidecars MUST be sent in (slot, column_index) order."
          },
          {
            "id": "INV-dcsbr-max-response",
            "text": "The response MUST contain no more than count * NUMBER_OF_COLUMNS data column sidecars."
          },
          {
            "id": "INV-dcsbr-max-request",
            "text": "No more than MAX_REQUEST_DATA_COLUMN_SIDECARS may be in the response."
          },
          {
            "id": "INV-dcsbr-single-chain",
            "text": "Clients MUST respond with data column sidecars consistent from a single chain within the context of the request."
          },
          {
            "id": "INV-dcsbr-fork-choice",
            "text": "Clients MUST respond with data columns from their view of the current fork choice."
          },
          {
            "id": "INV-dcsbr-backfill-required",
            "text": "Nodes starting from a recent weak subjectivity checkpoint MUST backfill the local data columns database to at least data_column_serve_range."
          }
        ],
        "preconditions": [],
        "postconditions": [],
        "state_transitions": [],
        "functions": [],
        "data_structures": [
          {
            "id": "DS-dcsbr-request",
            "name": "DataColumnSidecarsByRange Request",
            "type": "SSZ Container",
            "protocol_id": "/eth2/beacon_chain/req/data_column_sidecars_by_range/1/",
            "fields": [
              {"name": "start_slot", "type": "Slot"},
              {"name": "count", "type": "uint64"},
              {"name": "columns", "type": "List[ColumnIndex, NUMBER_OF_COLUMNS]"}
            ]
          },
          {
            "id": "DS-dcsbr-response",
            "name": "DataColumnSidecarsByRange Response",
